<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref} from 'vue'
import {useI18n} from 'vue-i18n'
import {quotaFollowAPI as api,type FollowConfig,type FollowRuntime,type GroupRule,type ResetRecord,type RecordDetail,type Discovery,type FollowEvent} from '@/api/quota-follow'
import {getAll} from '@/api/admin/groups'
import type {AdminGroup} from '@/types'
import {useAppStore} from '@/stores/app'
import {extractApiErrorMessage} from '@/utils/apiError'
import BaseDialog from '@/components/common/BaseDialog.vue'
import SystemUpdatePanel from '@/features/system-update/SystemUpdatePanel.vue'

const {t,te}=useI18n(),app=useAppStore()
const label=(key:string)=>te(`quotaFollow.${key}`)?t(`quotaFollow.${key}`):key
const groups=ref<AdminGroup[]>([]),runtime=ref<FollowRuntime[]>([]),revision=ref(1)
const config=reactive<FollowConfig>({enabled:false,min_interval_minutes:10,max_interval_minutes:15,groups:[]})
const saved=ref(''),selectedGroupID=ref<number|null>(null)
const availableGroups=computed(()=>groups.value.filter(g=>g.platform==='openai'&&g.subscription_type==='subscription'&&!config.groups.some(rule=>rule.group_id===g.id)))
const editable=(value:FollowConfig):FollowConfig=>({enabled:value.enabled,min_interval_minutes:value.min_interval_minutes,max_interval_minutes:value.max_interval_minutes,groups:value.groups.map(g=>({group_id:g.group_id,enabled:g.enabled,observe_only:g.observe_only,reset_daily_enabled:g.reset_daily_enabled,reset_weekly_enabled:g.reset_weekly_enabled}))})
const dirty=computed(()=>JSON.stringify(editable(config))!==saved.value)
const loading=ref(false),saving=ref(false),error=ref(''),items=ref<ResetRecord[]>([]),total=ref(0),page=ref(1),selected=ref<RecordDetail|null>(null),reconciling=ref(false)
const events=ref<FollowEvent[]>([]),eventPage=ref(1),eventTotal=ref(0),eventDetail=ref<unknown>(null)
const preview=ref<Discovery|null>(null),resetRule=ref<GroupRule|null>(null),previewing=ref(false),resetting=ref(false),resetRequestID=ref(''),acceptedEventID=ref<number|null>(null)
const reviewNote=ref('')
const filter=reactive({group_id:'',source:'',window:'',status:'',keyword:'',from:'',to:''})
const time=(value:string|null|undefined)=>value?new Date(value).toLocaleString():'—'
const groupName=(id:number|null)=>groups.value.find(g=>g.id===id)?.name??`#${id??'—'}`
const stateFor=(id:number)=>runtime.value.find(r=>r.group_id===id)
const resetWindows=(g:GroupRule)=>[...(g.reset_daily_enabled?['daily']:[]),...(g.reset_weekly_enabled?['weekly']:[])]
function addGroup(){if(selectedGroupID.value===null)return;config.groups.push({group_id:selectedGroupID.value,enabled:false,observe_only:true,reset_daily_enabled:false,reset_weekly_enabled:true});selectedGroupID.value=null}
async function loadEvents(){const result=await api.events(eventPage.value);events.value=result.items;eventTotal.value=result.total}
async function inspectEvent(id:number){try{eventDetail.value=await api.event(id)}catch(e){app.showError(extractApiErrorMessage(e,label('failure')))}}
async function records(){const {from,to,group_id,...rest}=filter;const result=await api.records({...rest,group_id:group_id?Number(group_id):undefined,from:from?new Date(from).toISOString():undefined,to:to?new Date(to).toISOString():undefined,page:page.value,page_size:20});items.value=result.items;total.value=result.total}
async function refresh(loadConfig=false){if(loading.value)return;loading.value=true;error.value='';try{
 if(loadConfig){const value=await api.config();revision.value=value.revision;Object.assign(config,editable(value));saved.value=JSON.stringify(editable(value))}
 const results=await Promise.allSettled([getAll(),api.runtime(),records(),loadEvents()]);if(results[0].status==='fulfilled')groups.value=results[0].value;if(results[1].status==='fulfilled')runtime.value=results[1].value
 error.value=results.filter((r):r is PromiseRejectedResult=>r.status==='rejected').map(r=>extractApiErrorMessage(r.reason,label('failure'))).join('；')
 }catch(e){error.value=extractApiErrorMessage(e,label('failure'))}finally{loading.value=false}}
async function save(){saving.value=true;try{const value=await api.save(editable(config),revision.value);revision.value=value.revision;Object.assign(config,editable(value));saved.value=JSON.stringify(editable(value));app.showSuccess(label('saved'));await refresh()}catch(e){app.showError(extractApiErrorMessage(e,label('failure')))}finally{saving.value=false}}
async function search(){try{await records()}catch(e){app.showError(extractApiErrorMessage(e,label('failure')))}}
async function detail(id:number){try{selected.value=await api.detail(id);reviewNote.value=''}catch(e){app.showError(extractApiErrorMessage(e,label('failure')))}}
async function eventTurn(step:number){eventPage.value+=step;try{await loadEvents()}catch(e){app.showError(extractApiErrorMessage(e,label('failure')))}}
async function openReset(rule:GroupRule){if(dirty.value||previewing.value)return;previewing.value=true;acceptedEventID.value=null;try{
 const found=await api.discovery(rule.group_id);preview.value=found;resetRule.value={...rule}
 const key=`quota-follow-reset:${rule.group_id}:${revision.value}`
 resetRequestID.value=sessionStorage.getItem(key)??crypto.randomUUID();sessionStorage.setItem(key,resetRequestID.value)
 }catch(e){app.showError(extractApiErrorMessage(e,label('failure')))}finally{previewing.value=false}}
function closeReset(){if(resetting.value)return;preview.value=null;resetRule.value=null}
async function immediateReset(){if(!resetRule.value||!preview.value||dirty.value||resetting.value||acceptedEventID.value)return;resetting.value=true;try{
 const result=await api.resetNow({group_id:resetRule.value.group_id,expected_revision:revision.value,request_id:resetRequestID.value});acceptedEventID.value=result.event_id
 sessionStorage.removeItem(`quota-follow-reset:${resetRule.value.group_id}:${revision.value}`)
 app.showSuccess(label('resetSubmitted'));await refresh()
 }catch(e){app.showError(extractApiErrorMessage(e,label('failure')))}finally{resetting.value=false}}
async function reconcile(){if(!selected.value?.batch)return;reconciling.value=true;try{await api.reconcile(selected.value.batch.id);await detail(selected.value.record.id);app.showSuccess(label('reconciled'))}catch(e){app.showError(extractApiErrorMessage(e,label('failure')))}finally{reconciling.value=false}}
async function retryFailed(){if(!selected.value?.batch||!window.confirm(label('retryConfirm')))return;reconciling.value=true;try{const result=await api.retry(selected.value.batch.id);app.showSuccess(`${label('resetSubmitted')} #${result.event_id}`);await refresh()}catch(e){app.showError(extractApiErrorMessage(e,label('failure')))}finally{reconciling.value=false}}
async function acknowledge(){if(!selected.value?.batch||!reviewNote.value||!window.confirm(label('reviewConfirm')))return;reconciling.value=true;try{await api.acknowledge(selected.value.batch.id,reviewNote.value);await detail(selected.value.record.id);await refresh()}catch(e){app.showError(extractApiErrorMessage(e,label('failure')))}finally{reconciling.value=false}}
let poll:ReturnType<typeof setInterval>|undefined
onMounted(()=>{void refresh(true);poll=setInterval(()=>{if(!saving.value)void refresh()},10000)})
onUnmounted(()=>{if(poll)clearInterval(poll)})
</script>

<template>
 <main class="enhance-page enhance-shell space-y-6 p-4 pt-3 sm:p-6 sm:pt-4">
  <header><div class="mb-2 flex flex-wrap items-center gap-3"><p class="text-sm font-semibold text-primary-600">sub2api++</p><SystemUpdatePanel /></div><h1 class="text-2xl font-bold sm:text-3xl">{{label('title')}}</h1><p class="mt-3 text-gray-500">{{label('description')}}</p></header>
  <p class="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900 dark:border-amber-800 dark:bg-amber-950/30 dark:text-amber-200" data-test="boundary">{{label('boundary')}}</p>
  <p v-if="error" role="alert" class="text-red-600">{{error}}</p>
  <form class="card space-y-5" @submit.prevent="save">
   <div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-xl font-semibold">{{label('settings')}}</h2><span class="text-sm text-gray-500">{{label('revision')}} {{revision}}</span></div>
   <label class="flex items-center gap-2"><input v-model="config.enabled" type="checkbox" :disabled="saving||!saved" data-test="enabled">{{label('enabled')}}</label>
   <div class="grid gap-4 sm:grid-cols-2"><label class="space-y-2"><span class="label">{{label('minInterval')}}</span><input v-model.number="config.min_interval_minutes" class="input" type="number" min="1" required></label><label class="space-y-2"><span class="label">{{label('maxInterval')}}</span><input v-model.number="config.max_interval_minutes" class="input" type="number" :min="config.min_interval_minutes" required></label></div>
   <div class="flex flex-wrap items-end gap-3"><label class="min-w-0 flex-1 space-y-2"><span class="label">{{label('addGroup')}}</span><select v-model="selectedGroupID" :disabled="saving" class="input" data-test="group"><option :value="null">{{label('chooseGroup')}}</option><option v-for="group in availableGroups" :key="group.id" :value="group.id">{{group.name}} · #{{group.id}}</option></select></label><button class="btn btn-secondary" type="button" :disabled="selectedGroupID===null||saving" data-test="add-group" @click="addGroup">{{label('add')}}</button></div>
   <p v-if="!config.groups.length" class="text-sm text-gray-500">{{label('noGroups')}}</p>
   <fieldset v-for="(rule,index) in config.groups" :key="rule.group_id" class="space-y-4 rounded-xl border border-gray-200 p-4 dark:border-dark-700" data-test="group-rule" :disabled="saving">
    <legend class="px-2 font-semibold">{{groupName(rule.group_id)}} · #{{rule.group_id}}</legend>
    <div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><label class="flex items-center gap-2"><input v-model="rule.enabled" type="checkbox">{{label('groupEnabled')}}</label><label class="flex items-center gap-2"><input v-model="rule.observe_only" type="checkbox" data-test="observe">{{label('observe')}}</label><label class="flex items-center gap-2"><input v-model="rule.reset_daily_enabled" type="checkbox">{{label('daily')}}</label><label class="flex items-center gap-2"><input v-model="rule.reset_weekly_enabled" type="checkbox">{{label('weekly')}}</label></div>
    <div v-if="stateFor(rule.group_id)" class="grid gap-2 text-sm text-gray-500 sm:grid-cols-2"><p>{{label('progress')}}：{{stateFor(rule.group_id)!.account_states.filter(s=>s.candidate_reset_at&&!s.error&&!s.baseline_rebased).length}} / {{stateFor(rule.group_id)!.account_states.length}}</p><p>{{label('subscriptionCount')}}：{{stateFor(rule.group_id)!.subscription_count}}</p><p>{{label('lastCheck')}}：{{time(stateFor(rule.group_id)!.last_checked_at)}}</p><p>{{label('nextCheck')}}：{{time(stateFor(rule.group_id)!.next_check_at)}}</p></div>
    <p v-if="stateFor(rule.group_id)?.last_error" class="text-sm text-red-600" role="status">{{stateFor(rule.group_id)!.last_error}}</p>
    <div class="flex flex-wrap gap-3"><button class="btn btn-secondary" type="button" :disabled="dirty||previewing||!resetWindows(rule).length" data-test="immediate-reset" @click="openReset(rule)">{{label('immediateReset')}}</button><button class="btn btn-secondary" type="button" @click="config.groups.splice(index,1)">{{label('removeGroup')}}</button></div>
   </fieldset>
   <p class="text-sm text-gray-500">{{label('eventHint')}}</p><p v-if="dirty" class="text-sm text-amber-700 dark:text-amber-300">{{label('saveFirst')}}</p>
   <div class="flex flex-wrap gap-3"><button class="btn btn-primary" type="submit" :disabled="saving||loading">{{label(saving?'saving':'save')}}</button><button class="btn btn-secondary" type="button" :disabled="loading" @click="refresh()">{{label('refresh')}}</button><button class="btn btn-secondary" type="button" :disabled="loading||saving" @click="refresh(true)">{{label('reloadConfig')}}</button></div>
  </form>
  <section v-for="group in runtime" :key="group.group_id" class="card space-y-4"><h2 class="text-xl font-semibold">{{groupName(group.group_id)}} · {{label('accountStates')}}</h2><div class="overflow-auto"><table class="table"><thead><tr><th>{{label('account')}}</th><th>{{label('utilization')}}</th><th>{{label('nextReset')}}</th><th>{{label('candidate')}}</th><th>{{label('sampled')}}</th><th>{{label('result')}}</th></tr></thead><tbody><tr v-for="state in group.account_states" :key="state.account.id"><td>{{state.account.name}} #{{state.account.id}}</td><td>{{state.utilization===null?'—':`${state.utilization}%`}}</td><td>{{time(state.next_reset_at)}}</td><td>{{time(state.candidate_reset_at)}}</td><td>{{time(state.fetched_at)}}</td><td>{{state.error||(state.baseline_rebased?label('rebasing'):label(state.candidate_reset_at?'confirmed':'waiting'))}}</td></tr></tbody></table><p v-if="!group.account_states.length" class="py-4 text-gray-500">{{label('waitingBaseline')}}</p></div></section>
  <section class="card space-y-4" data-test="records"><h2 class="text-xl font-semibold">{{label('records')}}</h2><p class="text-sm text-gray-500">{{label('recordsHint')}}</p>
   <form class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4" @submit.prevent="page=1;search()"><label><span class="label">{{label('group')}}</span><select v-model="filter.group_id" class="input"><option value="">{{label('all')}}</option><option v-for="g in groups" :key="g.id" :value="String(g.id)">{{g.name}}</option></select></label><label><span class="label">{{label('source')}}</span><select v-model="filter.source" class="input"><option value="">{{label('all')}}</option><option value="enhance">{{label('enhance')}}</option><option value="sub2api">{{label('sub2api')}}</option></select></label><label><span class="label">{{label('window')}}</span><select v-model="filter.window" class="input"><option value="">{{label('all')}}</option><option value="daily">{{label('daily')}}</option><option value="weekly">{{label('weekly')}}</option></select></label><label><span class="label">{{label('result')}}</span><select v-model="filter.status" class="input"><option value="">{{label('all')}}</option><option v-for="status in ['pending','inflight','succeeded','failed','skipped','uncertain']" :key="status" :value="status">{{label(status)}}</option></select></label><label><span class="label">{{label('keyword')}}</span><input v-model="filter.keyword" class="input"></label><label><span class="label">{{label('from')}}</span><input v-model="filter.from" class="input" type="datetime-local"></label><label><span class="label">{{label('to')}}</span><input v-model="filter.to" class="input" type="datetime-local"></label><button class="btn btn-secondary self-end" type="submit">{{label('filter')}}</button></form>
   <div class="overflow-auto"><table class="table"><thead><tr><th>{{label('time')}}</th><th>{{label('group')}}</th><th>{{label('subscription')}}</th><th>{{label('user')}}</th><th>{{label('source')}}</th><th>{{label('trigger')}}</th><th>{{label('window')}}</th><th>{{label('usageChange')}}</th><th>{{label('result')}}</th><th>{{label('details')}}</th></tr></thead><tbody><tr v-for="record in items" :key="record.id"><td>{{time(record.occurred_at)}}</td><td>{{record.group_id?groupName(record.group_id):'—'}}</td><td>{{record.subscription_id??label('legacy')}}</td><td>{{record.username}} #{{record.user_id}}</td><td>{{label(record.source)}} · {{label(record.evidence_type)}}</td><td>{{label(record.source_detail)}}</td><td>{{label(record.window??'—')}}</td><td>{{record.before_usage_usd??'—'}} → {{record.after_usage_usd??'—'}}</td><td>{{label(record.status)}}</td><td><button class="text-primary-600 underline" @click="detail(record.id)">{{label('details')}}</button></td></tr></tbody></table><p v-if="!items.length" class="py-8 text-center text-gray-500">{{label('empty')}}</p></div>
   <footer class="flex items-center justify-end gap-3"><span>{{total}} · {{page}}</span><button class="btn btn-secondary" :disabled="page<=1" :aria-label="label('previous')" @click="page--;search()">←</button><button class="btn btn-secondary" :disabled="page*20>=total" :aria-label="label('next')" @click="page++;search()">→</button></footer>
  </section>
  <section class="card space-y-4"><h2 class="text-xl font-semibold">{{label('events')}}</h2><div class="overflow-auto"><table class="table"><thead><tr><th>ID</th><th>{{label('group')}}</th><th>{{label('time')}}</th><th>{{label('subscriptionCount')}}</th><th>{{label('result')}}</th><th>{{label('details')}}</th></tr></thead><tbody><tr v-for="event in events" :key="event.id"><td>{{event.id}}</td><td>{{event.group_id?groupName(event.group_id):label('legacy')}}</td><td>{{time(event.reset_at)}}</td><td>{{event.subscription_count}}</td><td>{{label(event.status)}}</td><td><button class="text-primary-600 underline" @click="inspectEvent(event.id)">{{label('details')}}</button></td></tr></tbody></table></div><footer class="flex items-center justify-end gap-3"><span>{{eventTotal}} · {{eventPage}}</span><button class="btn btn-secondary" :disabled="eventPage<=1" :aria-label="label('previous')" @click="eventTurn(-1)">←</button><button class="btn btn-secondary" :disabled="eventPage*20>=eventTotal" :aria-label="label('next')" @click="eventTurn(1)">→</button></footer></section>
  <BaseDialog :show="!!preview" :title="label('immediateResetConfirmTitle')" @close="closeReset"><template v-if="preview&&resetRule"><p class="text-sm text-red-700 dark:text-red-200">{{label('immediateResetConfirm')}}</p><dl class="my-4 space-y-2 text-sm"><div><dt>{{label('group')}}</dt><dd>{{preview.group_name}} #{{preview.group_id}}</dd></div><div><dt>{{label('subscriptionCount')}}</dt><dd>{{preview.subscriptions.length}}</dd></div><div><dt>{{label('window')}}</dt><dd>{{resetWindows(resetRule).map(label).join('、')}}</dd></div></dl><p v-if="acceptedEventID" role="status">{{label('resetSubmitted')}} #{{acceptedEventID}}</p></template><template #footer><div class="flex gap-3"><button class="btn btn-secondary" :disabled="resetting" @click="closeReset">{{label('close')}}</button><button v-if="!acceptedEventID" class="btn btn-primary" :disabled="resetting||!preview?.subscriptions.length||dirty" data-test="confirm-immediate-reset" @click="immediateReset">{{label(resetting?'resetting':'confirm')}}</button></div></template></BaseDialog>
  <BaseDialog :show="!!selected" :title="label('recordDetail')" @close="selected=null"><template v-if="selected"><p v-if="selected.record.error_message" class="text-red-600">{{selected.record.error_message}}</p><div v-if="selected.batch" class="my-4 space-y-3"><p>{{label('batch')}} #{{selected.batch.id}} · {{label(selected.batch.status)}}</p><p class="text-sm text-gray-500">{{label('reconcileHint')}}</p><button class="btn btn-secondary" :disabled="reconciling||['pending','inflight'].includes(selected.batch.status)" @click="reconcile">{{label('reconcile')}}</button><button v-if="['failed','partial'].includes(selected.batch.status)" class="btn btn-secondary" :disabled="reconciling" @click="retryFailed">{{label('retryFailed')}}</button><div v-if="selected.batch.status==='uncertain'" class="space-y-2"><label><span class="label">{{label('reviewNote')}}</span><textarea v-model="reviewNote" class="input" rows="3" /></label><button class="btn btn-secondary" :disabled="reconciling||!reviewNote" @click="acknowledge">{{label('acknowledge')}}</button></div></div><details open><summary>{{label('raw')}}</summary><pre class="mt-3 overflow-auto whitespace-pre-wrap break-all text-xs">{{JSON.stringify(selected,null,2)}}</pre></details></template></BaseDialog>
  <BaseDialog :show="!!eventDetail" :title="label('events')" @close="eventDetail=null"><pre class="overflow-auto whitespace-pre-wrap break-all text-xs">{{JSON.stringify(eventDetail,null,2)}}</pre></BaseDialog>
 </main>
</template>
